const semesters=[
['Probabilités et statistique','Programmation orientée objet avancée','Programmation système','Réseaux informatiques avancés','Traitement numérique du signal','TEC / Anglais','Innovation et propriété intellectuelle'],
['Apprentissage automatique et apprentissage profond','Architecture avancée','Communication numérique','Ingénierie des données','Sécurité informatique','Méthodologie de la recherche scientifique','Culture entrepreneuriale'],
['Big Data','Théorie des graphes','Vision par ordinateur','Traitement de la vidéo','Option Informatique et IA : ingénierie de modèles et de langages, programmation concurrente et parallèle, applications à la vision 3D et au TAL','Option Réseaux et Télécommunications : microondes, technologies sans fil, traitement des antennes'],
['Projet de fin d’études et initiation à la recherche au sein d’une équipe']
];
function showMaster(){openDialog(heading('FORMATION / MASTER IT','Informatique & Télécommunications')+`<p>Depuis 2006, le Master associe approfondissement scientifique, spécialisation et formation méthodologique aux métiers de la recherche. Le programme ci-dessous est celui présenté dans le rapport pour la maquette depuis 2024.</p><div class="tabs" role="tablist" aria-label="Semestres">${semesters.map((_,i)=>`<button role="tab" id="sem-tab-${i}" aria-controls="semester-content" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-sem="${i}">Semestre ${i+1}</button>`).join('')}</div><div id="semester-content" role="tabpanel" aria-labelledby="sem-tab-0"></div><h3>Accès à la formation</h3><p>Le rapport mentionne les licences en informatique, mathématiques ou physique, ou un diplôme équivalent, avec étude du dossier puis entretien. Les modalités et le calendrier de chaque campagne sont à consulter auprès de la formation.</p><a class="button primary" href="master-it/index.html" target="_blank" rel="noopener">Consulter le site du Master <span>↗</span></a>`);
const update=i=>{content.querySelectorAll('[data-sem]').forEach(b=>{const selected=Number(b.dataset.sem)===i;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1});content.querySelector('#semester-content').setAttribute('aria-labelledby',`sem-tab-${i}`);content.querySelector('#semester-content').innerHTML=`<ul class="program-list">${semesters[i].map(x=>`<li>${x}</li>`).join('')}</ul>`};update(0);content.querySelectorAll('[data-sem]').forEach(b=>{b.addEventListener('click',()=>update(Number(b.dataset.sem)));b.addEventListener('keydown',e=>{if(['ArrowRight','ArrowLeft','Home','End'].includes(e.key)){e.preventDefault();let i=Number(b.dataset.sem);i=e.key==='Home'?0:e.key==='End'?3:(i+(e.key==='ArrowRight'?1:3))%4;update(i);content.querySelector(`[data-sem="${i}"]`).focus()}})})}
let membersPromise;
async function showMembers(){openDialog(heading('COMMUNAUTÉ / ANNUAIRE','Les membres du LRIT')+`<p>Enseignants-chercheurs permanents et membres associés recensés dans la documentation du laboratoire.</p><div class="search-controls"><input id="member-search" type="search" placeholder="Rechercher un nom, un établissement…" aria-label="Rechercher dans l’annuaire"><select id="member-status" aria-label="Filtrer par statut"><option value="all">Tous les membres</option><option value="permanent">Membres permanents</option><option value="associe">Membres associés</option></select></div><div id="member-count" class="result-count" aria-live="polite">Chargement de l’annuaire…</div><div id="member-results" class="table-wrap"></div><div class="notice">PES : professeur de l’enseignement supérieur · MCH : maître de conférences habilité · MC : maître de conférences. Les grades et affiliations reprennent les données du rapport.</div>`);
try{membersPromise??=fetch('membres.json').then(r=>{if(!r.ok)throw Error('Annuaire indisponible');return r.json()});const members=await membersPromise;if(!content.querySelector('#member-search'))return;const input=content.querySelector('#member-search'),select=content.querySelector('#member-status');const render=()=>{const q=normalize(input.value.trim()),status=select.value;const list=members.filter(m=>(status==='all'||m.statut===status)&&normalize(`${m.prenom} ${m.nom} ${m.etablissement}`).includes(q));content.querySelector('#member-count').textContent=`${list.length} membre${list.length>1?'s':''} sur ${members.length}`;content.querySelector('#member-results').innerHTML=list.length?`<table><caption class="skip">Annuaire du LRIT</caption><thead><tr><th scope="col">Nom & prénom</th><th scope="col">Établissement</th><th scope="col">Grade</th></tr></thead><tbody>${list.map(m=>`<tr><td>${escapeHTML(m.prenom)} <strong>${escapeHTML(m.nom)}</strong><br><small>${m.statut==='permanent'?'Membre permanent':'Membre associé'}</small></td><td>${escapeHTML(m.etablissement||'Non précisé')}</td><td>${escapeHTML(m.grade||'—')}</td></tr>`).join('')}</tbody></table>`:'<p class="empty">Aucun membre ne correspond à votre recherche. Essayez un autre nom ou établissement.</p>'};input.addEventListener('input',render);select.addEventListener('change',render);render()}catch(e){if(content.querySelector('#member-count'))content.querySelector('#member-count').textContent='L’annuaire ne peut pas être chargé. Fermez puis réessayez.'}}
function showPublications(){openDialog(heading('RECHERCHE / PUBLICATIONS','Une sélection de travaux')+`<p>Quelques publications de 2025 recensées dans le rapport d’activité. Cette sélection donne un aperçu des domaines de recherche du laboratoire.</p><div class="search-controls"><input id="pub-search" type="search" aria-label="Rechercher une publication" placeholder="Rechercher un titre, une revue…"></div><div id="pub-results" aria-live="polite"></div>`);const input=content.querySelector('#pub-search');const render=()=>{const q=normalize(input.value);const list=publications.filter(p=>normalize(`${p.title} ${p.journal} ${p.tag}`).includes(q));content.querySelector('#pub-results').innerHTML=list.length?list.map(p=>`<article class="publication"><small>${p.year} · ${p.tag.toUpperCase()}</small><h3>${p.title}</h3><p>${p.journal}</p></article>`).join(''):'<p class="empty">Aucune publication ne correspond à votre recherche.</p>'};input.addEventListener('input',render);render()}
const pages={
histoire:()=>heading('LABORATOIRE / HISTOIRE','Une histoire de transmission')+`<p>Le groupe Signaux, Communications et Multimédia (GSCM), créé en 1993, constitue une origine scientifique du LRIT. Le laboratoire s’est développé autour du traitement des contenus numériques, des réseaux et des télécommunications.</p><h3>Des étapes structurantes</h3><ul><li><strong>2001 :</strong> DESA en informatique et télécommunications ; constitution du pôle de compétences STIC.</li><li><strong>2006 :</strong> mise en place du Master de recherche.</li><li><strong>2009 :</strong> reconnaissance comme unité de recherche associée au CNRST et mise en place de la Licence professionnelle.</li><li><strong>2017–2022 :</strong> direction du Pr Mohammed Ouadou, à la suite du Pr Driss Aboutajdine.</li><li><strong>Depuis 2022 :</strong> direction du Pr Khalid Minaoui.</li></ul><p>Le laboratoire poursuit un projet collectif associant recherche, formation et coopération, en lien avec les priorités scientifiques et les besoins socio-économiques.</p>`,
projets:()=>heading('RECHERCHE / COOPÉRATIONS','Des savoirs en dialogue')+`<p>Le rapport retrace des projets universitaires et des coopérations avec le monde socio-économique. Voici quelques exemples historiques.</p><article class="project-entry"><small>CRTS · 2011–2013</small><h3>Télédétection & environnement marin</h3><p>Étude par imagerie satellitaire de l’upwelling et de la qualité des eaux marines le long de la côte atlantique marocaine. Responsable : Pr Khalid Minaoui.</p></article><article class="project-entry"><small>OCP · 2003–2006</small><h3>Supervision de parc mobile</h3><p>Supervision en temps réel du parc mobile de l’OCP : GPS, radio numérique et recherche-développement.</p></article><article class="project-entry"><small>MAROC TELECOM · PROJETS HISTORIQUES</small><h3>Sécurité & contenus multimédias</h3><p>Reconnaissance faciale et multimodale, filtrage de contenus et protection de la vidéo à la demande par tatouage numérique.</p></article><h3>Coopération académique</h3><p>Le rapport décrit des échanges, des coencadrements et des cotutelles avec des partenaires en France, en Espagne, au Canada, aux États-Unis et en Tunisie.</p>`,
doctorat:()=>heading('FORMATION / DOCTORAT','Se former par la recherche')+`<p>Le doctorat au LRIT s’inscrit dans les domaines scientifiques du laboratoire : intelligence artificielle, traitement du signal et des images, données, réseaux, télécommunications et systèmes numériques.</p><h3>Un parcours au sein d’une équipe</h3><ul><li>Construction d’une problématique scientifique et d’une démarche de recherche.</li><li>Encadrement par les enseignants-chercheurs du laboratoire.</li><li>Participation à la vie scientifique : séminaires, publications et conférences.</li><li>Collaborations, coencadrements et cotutelles selon les projets.</li></ul><p>Les sujets ouverts, les critères d’admission, les financements et les échéances dépendent de chaque campagne de recrutement. Consultez les informations institutionnelles de l’Université Mohammed V de Rabat.</p><a class="button primary" href="https://www.um5.ac.ma/um5/formation-doctorale" target="_blank" rel="noopener">Informations institutionnelles du CEDoc — UM5 <span>↗</span></a>`,
rapport:()=>heading('DOCUMENTATION / 2003–2026','Le rapport d’activité en bref')+`<p>Le rapport d’activité présente la trajectoire du laboratoire, ses équipes, ses travaux et ses actions de formation. Le site en propose les informations essentielles.</p><ol class="outline-list"><li>Présentation générale et objectifs du laboratoire</li><li>Thématiques de recherche</li><li>Membres permanents, associés et doctorants</li><li>Production scientifique, thèses et projets de recherche</li><li>Manifestations scientifiques et distinctions</li><li>Formations</li><li>Activités associatives, culturelles et sportives</li></ol><div class="notice">Le rapport intégral sera proposé dans cet espace ultérieurement.</div>`,
vie:()=>heading('COMMUNAUTÉ / VIE SCIENTIFIQUE','Échanger et transmettre')+`<p>Le laboratoire participe à la vie scientifique à travers des conférences, des journées de recherche, des séminaires et des formations.</p><h3>Des rencontres scientifiques</h3><p>L’histoire du LRIT est notamment liée à ISIVC, ICISP, ISCCSP et WOTIC. Ces rencontres favorisent les échanges entre chercheurs, doctorants et partenaires.</p><h3>L’Association des Jeunes Chercheurs</h3><p>L’Association des Jeunes Chercheurs en Informatique et Télécommunications (AJCIT) contribue aux activités scientifiques, aux formations et à la vie associative autour du laboratoire.</p><p>Les activités présentées dans le rapport couvrent aussi les initiatives culturelles, sportives et sociales.</p><a class="text-link" href="mailto:association.ajcit@gmail.com">Contacter l’AJCIT <span>↗</span></a>`,
mentions:()=>heading('INFORMATIONS','À propos de ce site')+`<p>Ce site présente les informations essentielles du Laboratoire de Recherche en Informatique et Télécommunications (LRIT), Faculté des Sciences de Rabat, Université Mohammed V.</p><p>Les textes, les portraits et le logo proviennent de la documentation du laboratoire fourni pour la création de ce site. Les effectifs de l’annuaire correspondent à ceux recensés dans le rapport ; ils ne constituent pas un décompte en temps réel.</p><p>Les sept domaines de recherche regroupent les thématiques du rapport pour faciliter leur consultation. La liste de publications est une sélection.</p><p>La recherche dans l’annuaire et dans les publications s’effectue dans votre navigateur. Aucun formulaire de collecte de données ni outil de suivi publicitaire n’est intégré à cette version du site.</p>`
};
document.querySelectorAll('[data-modal]').forEach(b=>b.addEventListener('click',()=>{const key=b.dataset.modal;if(key==='annuaire')showMembers();else if(key==='master')showMaster();else if(key==='publications')showPublications();else if(pages[key])openDialog(pages[key]())}));
const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){nav.querySelectorAll('a').forEach(a=>a.classList.toggle('active',a.getAttribute('href').split('#')[1]===e.target.id))}})},{rootMargin:'-20% 0px -65% 0px'});
document.querySelectorAll('main section[id]').forEach(s=>observer.observe(s));

// Keep one navigation group open; close on Escape and outside interaction.
const navGroups=[...document.querySelectorAll('.nav-group')];navGroups.forEach(group=>group.addEventListener('toggle',()=>{if(group.open)navGroups.forEach(other=>{if(other!==group)other.open=false})}));document.addEventListener('click',e=>{if(!e.target.closest('.nav-group'))navGroups.forEach(g=>g.open=false)});document.addEventListener('keydown',e=>{if(e.key==='Escape')navGroups.forEach(g=>{if(g.open){g.open=false;g.querySelector('summary').focus()}})});
